import { calculateInterest } from "../../../src/lending/interest.js";

describe("calculateInterest", () => {
  it("compounds interest over whole years", () => {
    // Arrange
    const principal = 100000;

    // Act
    const interest = calculateInterest(principal, 10, 2);

    // Assert
    expect(interest).toBeCloseTo(21000);
  });

  it("returns zero interest for a zero rate", () => {
    // Arrange
    const principal = 50000;

    // Act
    const interest = calculateInterest(principal, 0, 5);

    // Assert
    expect(interest).toBe(0);
  });

  it("rejects a non-positive principal", () => {
    // Arrange
    const principal = 0;

    // Act
    const act = () => calculateInterest(principal, 10, 1);

    // Assert
    expect(act).toThrow(RangeError);
  });
});
